  values ('20000000-0000-4000-8000-000000000001', 'dog-mountain-snowshoe', 'Dog Mountain Snowshoe & City Views', (select id from public.activity_categories where slug = 'snowshoeing'),
    (select id from public.regions where slug = 'north-vancouver'), 'published', true, '/images/scenes/snow-forest.svg', 'A gentle first snowshoe of the season to a viewpoint over the whole city.', 'Our classic beginner snowshoe. We''ll wind through quiet old-growth on Mount Seymour to the Dog Mountain viewpoint, with Vancouver, the Fraser River and (on a clear day) Mount Baker laid out below. Perfect if you''re new to snowshoeing or want an easy social day in the snow.

We''ll stop for hot drinks at the viewpoint and take our time on the way back.',
    ((((now() at time zone 'America/Vancouver')::date + 2) + time '09:00') at time zone 'America/Vancouver'), ((((now() at time zone 'America/Vancouver')::date + 2) + time '13:00') at time zone 'America/Vancouver'), 'Mount Seymour Provincial Park', 5, 150,
    240, 'easy', 'Relaxed, with photo stops', 'none', 'No snowshoe experience needed — we''ll show you the basics.',
    'Comfortable walking 2–3 hours on rolling terrain.', array['Snowshoes (rentals available at the resort)','Waterproof winter boots','Insulated jacket and spare gloves','Headlamp','Microspikes for icy sections','Thermos with a hot drink']::text[], array['Sit pad','Sunglasses','Hand warmers']::text[], 'Bring a packed lunch, snacks and at least 1 L of water or a hot drink.',
    'Mount Seymour Road requires winter tires or chains (Nov 1 – Mar 31).', 'We go in light snow. Heavy snowfall or high winds may trigger a postponement 24h ahead.', 'Stay on the marked trail — First Lake area cliffs are hidden by snow. Headcount at trailhead and viewpoint.', 14,
    1, null,
    ((((now() at time zone 'America/Vancouver')::date + 2) + time '09:00') at time zone 'America/Vancouver') - interval '24 hours', ((((now() at time zone 'America/Vancouver')::date + 2) + time '09:00') at time zone 'America/Vancouver') - interval '48 hours',
    true, 'automatic', 0, 0,
    array['none']::public.payment_method[], null, '[{"label":"AllTrails: Dog Mountain","url":"https://www.alltrails.com/trail/canada/british-columbia/dog-mountain-trail"},{"label":"Mt Seymour conditions","url":"https://mtseymour.ca/conditions"}]'::jsonb,
    '[{"title":"What to expect","items":["Hot drink stop at the viewpoint","Snowshoe technique tips at the start","Optional post-hike lunch in Deep Cove"]}]'::jsonb, '[{"id":"snowshoe_rental","label":"Do you need to rent snowshoes?","required":true,"type":"yesno"}]'::jsonb, '{}'::text[], true, null,
