  values ('20000000-0000-4000-8000-000000000003', 'lynn-headwaters-norvan-falls', 'Lynn Headwaters to Norvan Falls', (select id from public.activity_categories where slug = 'hiking'),
    (select id from public.regions where slug = 'north-vancouver'), 'published', true, '/images/scenes/forest-falls.svg', 'A long, mellow valley walk through mossy rainforest to a thundering waterfall.', 'A classic rainforest day: we follow Lynn Creek up the valley on the Headwaters trail to Norvan Falls, returning on the Cedars Mill trail. Mostly gentle grade with a few rooty and rocky sections and creek crossings on bridges.',
    ((((now() at time zone 'America/Vancouver')::date + 9) + time '09:00') at time zone 'America/Vancouver'), ((((now() at time zone 'America/Vancouver')::date + 9) + time '14:30') at time zone 'America/Vancouver'), 'Lynn Headwaters Regional Park', 14, 350,
