    'Carpools encouraged; the Lynn Headwaters lot is small.', 'Expect rain. Creek levels rise after heavy rainfall; organizers will check conditions.', 'Register at the trailhead board. Regroup at every junction. Turnaround time 12:00.', 12,
    0, null,
    ((((now() at time zone 'America/Vancouver')::date + 9) + time '09:00') at time zone 'America/Vancouver') - interval '48 hours', ((((now() at time zone 'America/Vancouver')::date + 9) + time '09:00') at time zone 'America/Vancouver') - interval '48 hours',
