    (select id from public.regions where slug = 'west-vancouver'), 'published', false, '/images/scenes/snow-peak.svg', 'Steady climb through the Nordic area to a summit with ocean and island views.', 'From the Cypress Nordic area we climb the Hollyburn Peak trail to the summit. The final pitch is steep — poles and traction help. Summit views stretch to Vancouver Island on a clear day.',
