  values ('20000000-0000-4000-8000-000000000009', 'indian-arm-winter-paddle', 'Indian Arm Winter Paddle', (select id from public.activity_categories where slug = 'kayaking'),
    (select id from public.regions where slug = 'north-vancouver'), 'published', false, '/images/scenes/fjord-paddle.svg', 'Glassy winter water, snowy peaks and seals on a guided-pace sea kayak day.', 'Indian Arm is magical in winter: calm water, snow-capped peaks and almost no boat traffic. We''ll paddle from Deep Cove to Jug Island and Raccoon Island for lunch on the beach. Rental includes a drysuit, PFD and spray skirt.',
