insert into public.event_posts (event_id, author_id, body, is_announcement, pinned, created_at) values
  ('20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000003', 'Welcome everyone! Snow report looks great — about 40 cm of fresh snow at the base. Rentals open at 8:30. See you at the Rental Shop!', true, true, now() - interval '20 hours'),
